-- SBOM per default-branch push (feature, 2026-11-13). Generated by the api
-- outside any user pipeline (syft over `git archive` of the commit), stored
-- here so the repo landing page can show status + a direct download. One row
-- per (repo, commit); the newest rows are kept (retention in store/sboms.go).
CREATE TABLE sboms (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    repo_id uuid NOT NULL REFERENCES repositories(id) ON DELETE CASCADE,
    tenant_id uuid NOT NULL,
    commit_sha text NOT NULL,
    ref text NOT NULL DEFAULT '',
    status text NOT NULL DEFAULT 'pending', -- pending | running | ready | failed
    format text NOT NULL DEFAULT 'cyclonedx-json',
    spec_version text NOT NULL DEFAULT '',
    component_count int NOT NULL DEFAULT 0,
    document bytea,
    error text NOT NULL DEFAULT '',
    created_at timestamptz NOT NULL DEFAULT now(),
    started_at timestamptz,
    finished_at timestamptz,
    UNIQUE (repo_id, commit_sha)
);

CREATE INDEX sboms_repo_created_idx ON sboms (repo_id, created_at DESC);
CREATE INDEX sboms_tenant_idx ON sboms (tenant_id);
